import re
from datetime import date
def check(s):
    if not re.fullmatch(r'\d{4}-\d{2}-\d{2}', s):
        return 'shape'
    y, m, d = map(int, s.split('-'))
    try:
        date(y, m, d)
    except ValueError:
        return 'not a real date'
    return 'ok'
for s in ['2026-11-26', '2026-13-01', '26-11-2026', '2024-02-29', '2025-02-29']:
    print(s, check(s))

import re
def normalize(p):
    d = re.sub(r'\D', '', p)
    if len(d) == 11 and d.startswith('1'):
        d = d[1:]
    return d if len(d) == 10 else None
for p in ['(407) 645-2264', '+1 407 645 2264', '407.645.2264', '645-2264', '407-645-22644']:
    print(p, '->', normalize(p))

