import re
from datetime import date
pat = re.compile(r'^(?P<y>\d{4})-(?P<m>\d{2})-(?P<d>\d{2})$')
def check(s):
    m = pat.match(s)
    if not m:
        return 'shape fail'
    try:
        date(int(m['y']), int(m['m']), int(m['d']))
        return 'valid'
    except ValueError:
        return 'impossible date'
for s in ['2026-11-26', '2026-2-9', '2026-13-01', '2024-02-29', '1900-02-29', '2000-02-29']:
    print(s, check(s))
